import {useCallback, useRef, useState} from 'react'
import type {ChatInputRef} from '@github-ui/copilot-chat/components/ChatInput'
import {sendEvent} from '@github-ui/hydro-analytics'
import type {IcebreakerOption} from '../types/icebreaker'

const ICEBREAKERS_DISMISSED_KEY = 'AGENT_ICEBREAKERS_DISMISSED'

export function useIcebreakers({enabled, location, variant}: {enabled: boolean; location: string; variant?: string}) {
  const chatInputRef = useRef<ChatInputRef | null>(null)
  const textAreaRef = useRef<HTMLTextAreaElement | null>(null)
  const selectedIcebreakerRef = useRef<IcebreakerOption | null>(null)
  const [dismissed, setDismissed] = useState(() => {
    try {
      return localStorage.getItem(ICEBREAKERS_DISMISSED_KEY) === 'true'
    } catch {
      return false
    }
  })

  const visible = enabled && !dismissed

  const handleSelect = useCallback(
    (option: IcebreakerOption) => {
      selectedIcebreakerRef.current = option
      sendEvent('agent_sessions.icebreaker_click', {
        location,
        variant: variant ?? 'control',
        icebreaker_title: option.title,
      })
      chatInputRef.current?.setText(option.prompt)
      requestAnimationFrame(() => {
        const textarea = textAreaRef.current
        if (textarea) {
          textarea.focus()
          textarea.setSelectionRange(textarea.value.length, textarea.value.length)
        }
      })
    },
    [location, variant],
  )

  const handleDismiss = useCallback(() => {
    sendEvent('agent_sessions.icebreaker_dismiss', {
      location,
      variant: variant ?? 'control',
    })
    setDismissed(true)
    try {
      localStorage.setItem(ICEBREAKERS_DISMISSED_KEY, 'true')
    } catch {
      // localStorage unavailable
    }
  }, [location, variant])

  const handleIcebreakerSubmit = useCallback(
    (submittedPrompt: string) => {
      if (selectedIcebreakerRef.current) {
        const wasEdited = submittedPrompt.trim() !== selectedIcebreakerRef.current.prompt.trim()
        sendEvent('agent_sessions.icebreaker_submit', {
          location,
          variant: variant ?? 'control',
          icebreaker_title: selectedIcebreakerRef.current.title,
          prompt_was_edited: wasEdited,
        })
        selectedIcebreakerRef.current = null
      }
    },
    [location, variant],
  )

  return {
    chatInputRef,
    textAreaRef,
    visible,
    handleSelect,
    handleDismiss,
    handleIcebreakerSubmit,
  }
}
