import {XIcon} from '@primer/octicons-react'
import {Heading, IconButton} from '@primer/react'

import {clsx} from 'clsx'
import styles from './AgentIcebreakers.module.css'
import {getIcebreakers} from '../../constants/icebreakers'
import type {IcebreakerOption} from '../../types/icebreaker'

interface AgentIcebreakersProps {
  onSelect: (option: IcebreakerOption) => void
  onDismiss: () => void
  variant?: string
  location?: string
}

export function AgentIcebreakers({onSelect, onDismiss, variant}: AgentIcebreakersProps) {
  const icebreakers = getIcebreakers(variant)
  return (
    <div data-testid="agent-icebreakers">
      <div className={styles.header}>
        <Heading as="h3" className={styles.headerTitle}>
          Get started with agents
        </Heading>
        <IconButton
          variant="invisible"
          size="small"
          aria-label="Dismiss agents tips"
          icon={XIcon}
          onClick={onDismiss}
        />
      </div>
      <div className={styles.container}>
        {icebreakers.map(icebreaker => (
          <button
            key={icebreaker.title}
            type="button"
            className={styles.icebreaker}
            onClick={() => onSelect(icebreaker)}
            data-testid={`icebreaker-${icebreaker.title.toLowerCase().replace(/\s+/g, '-')}`}
          >
            <span className={styles.iconWrapper}>{icebreaker.icon}</span>
            <div className={styles.textContent}>
              <span className={styles.title}>{icebreaker.title}</span>
              <span className={styles.subheader}>{icebreaker.subheader}</span>
              {icebreaker.shortSubheader && (
                <span className={clsx(styles.subheader, styles.short)}>{icebreaker.shortSubheader}</span>
              )}
            </div>
          </button>
        ))}
      </div>
    </div>
  )
}
