import {LightBulbIcon, FileCodeIcon, TasklistIcon} from '@primer/octicons-react'
import type {IcebreakerOption} from '../types/icebreaker'

// Default icebreakers — slot 0 and slot 2 are constant across all variants.
// Slot 1 (middle) is replaced per-variant for experiments.
export const defaultIcebreakers: IcebreakerOption[] = [
  {
    title: 'Explain repository',
    subheader: 'Let the agent help you understand the codebase',
    icon: <LightBulbIcon size={16} className="fgColor-muted" />,
    prompt:
      'Explain this repository. Help me understand the codebase structure, key technologies used, and how the code is organized.',
  },
  {
    title: 'Improve test coverage',
    subheader: 'Analyze the codebase and improve coverage',
    icon: <FileCodeIcon size={16} className="fgColor-muted" />,
    prompt:
      'Analyze the test coverage of this codebase. Identify areas with missing or insufficient tests and add comprehensive test cases to improve coverage.',
  },
  {
    title: 'Create a plan',
    subheader: 'Plan with the agent before making changes to the codebase',
    shortSubheader: 'Plan before making changes to the codebase',
    icon: <TasklistIcon size={16} className="fgColor-muted" />,
    prompt:
      'Explore the codebase and create a detailed implementation plan for [INSERT IDEA HERE]. Ask clarifying questions if needed.',
    createPullRequest: false,
  },
]

// Per-variant overrides for the middle icebreaker (slot 1).
// Teams customize this during the experiment workshop.
export const variantMiddleIcebreaker: Record<string, IcebreakerOption> = {
  team_a: {
    title: 'Fix a bug',
    subheader: 'Find and fix an open issue in the codebase',
    icon: <FileCodeIcon size={16} className="fgColor-muted" />,
    prompt:
      'Look at the open issues in this repository, pick one that looks like a bug, and create a fix with tests. Explain your reasoning and the changes you made.',
  },
  team_b: {
    title: 'Add documentation',
    subheader: 'Improve the project documentation and README',
    icon: <FileCodeIcon size={16} className="fgColor-muted" />,
    prompt:
      'Review the existing documentation for this repository. Identify gaps or areas that could be improved, then update the README and add any missing documentation.',
  },
  team_c: {
    title: 'Refactor code',
    subheader: 'Identify and refactor code that could be cleaner',
    icon: <FileCodeIcon size={16} className="fgColor-muted" />,
    prompt:
      'Analyze this codebase for code smells, duplicated logic, or overly complex functions. Refactor the worst offenders while maintaining existing behavior and tests.',
  },
  team_d: {
    title: 'Add a new feature',
    subheader: 'Build a small feature to enhance the project',
    icon: <FileCodeIcon size={16} className="fgColor-muted" />,
    prompt:
      'Explore this repository and suggest a small but useful feature that could be added. Then implement it with proper tests and documentation.',
  },
}

export function getIcebreakers(variant?: string): IcebreakerOption[] {
  if (!variant || variant === 'control' || !(variant in variantMiddleIcebreaker)) {
    return defaultIcebreakers
  }
  const first = defaultIcebreakers[0]
  const middle = variantMiddleIcebreaker[variant]
  const last = defaultIcebreakers[2]
  if (first === undefined || middle === undefined || last === undefined) {
    return defaultIcebreakers
  }
  return [first, middle, last]
}
